import { existsSync } from 'node:fs';
import path from 'node:path';
import { CONVERT_BYTES_TO_MB, MAX_ASSET_SIZE } from '../../constants.js';
import { buildAgentManifest, buildAgentPackage } from './build-package.js';
/**
 * Builds the complete Web Function bundle for a `sanity.agent` resource from its
 * `src` source path, with the manifest INSIDE the zip. Asset prep is the sole
 * producer of this bundle: the Provider only reads the prepared bytes and never
 * builds, assembles, or merges a manifest, so the bundle emitted here is
 * complete -- a runnable root `index.mjs` bootstrap, eve's built node-server
 * under `.output/`, and the root `package.json` manifest. The platform deploys
 * it as a zip Web Function (`EntryPoint index.mjs`, `Runtime nodejs24.x`), which
 * loads the root `index.mjs`; a container layout (raw `.ts` + Dockerfile) never
 * boots there.
 *
 * The `sanityID` in the manifest is derived from the project scope (`auth.scopeId`);
 * `name`, `description`, and `region` come from the resource.
 *
 * The returned `assetParameter` is `src`, so once the bytes are stashed the
 * resource `src` is rewritten from the source path to the returned `AS-...` asset
 * id before deploy. A build failure (including a failed `eve build`) returns
 * `{success: false}`, which fails the CLI prep step before the Blueprints API is
 * called.
 */
export async function prepareAsset({ blueprintFileDir, resource, auth, }) {
    if (!resource.src)
        throw new Error('Resource src is required');
    const cleanup = async () => { };
    const agentPath = path.resolve(blueprintFileDir, resource.src);
    try {
        if (!auth?.scopeId) {
            throw new Error('A project scope is required to build the agent package manifest.');
        }
        if (!resource.region) {
            throw new Error('Resource region is required to build the agent package manifest.');
        }
        if (!existsSync(agentPath)) {
            throw new Error(`Agent source path not found: ${agentPath}`);
        }
        const manifest = buildAgentManifest(resource, auth.scopeId);
        const zip = await buildAgentPackage(agentPath, manifest);
        // Sum uncompressed entry sizes so the limit check reflects the zip size.
        const zipEntrySize = zip
            .getEntries()
            .map((entry) => entry.header.size)
            .reduce((a, b) => a + b, 0);
        if (zipEntrySize > MAX_ASSET_SIZE) {
            throw new Error(`Asset size of ${(zipEntrySize / CONVERT_BYTES_TO_MB).toFixed(2)} MB exceeds the maximum allowed size of 200 MB.`);
        }
        return {
            success: true,
            outputBuffer: await zip.toBufferPromise(),
            fileExtension: 'zip',
            assetParameter: 'src',
            cleanup,
            metadata: {
                assetBytes: zipEntrySize,
            },
        };
    }
    catch (err) {
        return { success: false, cleanup, error: err instanceof Error ? err.message : `${err}` };
    }
}
